export interface ConnectorConfig {
  trelloApiKey: string;
  trelloApiToken: string;
  trelloListId: string;
  trelloChecklistId: string;
  cardName: string;
  fetch?: typeof fetch;
}

export interface CalComWebhookPayload {
  triggerEvent: string;
  payload: {
    attendees: Array<{
      email: string;
      name: string;
      timeZone: string;
      language: { locale: string };
    }>;
    title: string;
    startTime: string;
    endTime: string;
    organizer: { email: string; name: string };
    uid: string;
    bookingId: number;
    status: string;
  };
}

export interface HandleResult {
  cardId: string;
  checkItemId: string;
  checkItemName: string;
}

async function handle(payload: CalComWebhookPayload, config: ConnectorConfig): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch;

  if (!payload.payload || !Array.isArray(payload.payload.attendees) || payload.payload.attendees.length === 0) {
    throw new Error('Payload must contain at least one attendee');
  }

  const firstAttendee = payload.payload.attendees[0];
  const attendeeValue = firstAttendee.email || firstAttendee.name;
  if (!attendeeValue) {
    throw new Error('First attendee must have either email or name');
  }

  const authParams = new URLSearchParams({
    key: config.trelloApiKey,
    token: config.trelloApiToken,
  });

  const listCardsUrl = `https://api.trello.com/1/lists/${encodeURIComponent(config.trelloListId)}/cards?${authParams}`;
  const listCardsResponse = await fetchImpl(listCardsUrl, { method: 'GET' });

  if (!listCardsResponse.ok) {
    throw new Error(
      `Failed to fetch cards from list: ${listCardsResponse.status} ${listCardsResponse.statusText} at GET /lists/${config.trelloListId}/cards`
    );
  }

  const cardsData = await listCardsResponse.json();
  const cards = Array.isArray(cardsData) ? cardsData : [cardsData];
  const card = cards.find((c: { id: string; name: string; idList: string }) => c.name === config.cardName);

  if (!card) {
    throw new Error(`Card with name "${config.cardName}" not found in list ${config.trelloListId}`);
  }

  const checkItemUrl = `https://api.trello.com/1/checklists/${encodeURIComponent(config.trelloChecklistId)}/checkItems?${authParams}`;
  const checkItemResponse = await fetchImpl(checkItemUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ name: attendeeValue }),
  });

  if (!checkItemResponse.ok) {
    throw new Error(
      `Failed to create checklist item: ${checkItemResponse.status} ${checkItemResponse.statusText} at POST /checklists/${config.trelloChecklistId}/checkItems`
    );
  }

  const checkItem = await checkItemResponse.json() as { id: string; name: string; state: string; idChecklist: string };

  return {
    cardId: card.id,
    checkItemId: checkItem.id,
    checkItemName: checkItem.name,
  };
}

